    let scores_arr = v.get("scores")?.as_array()?;
    let mut scores = Vec::new();
    for s in scores_arr {
        let vendor = s.get("vendor")?.as_str()?.to_string();
        let axis = |k: &str| -> Option<u8> {
            let n = s.get(k)?.as_u64()?;
            Some(n.clamp(1, 5) as u8)
