    }
    if scores.is_empty() {
        return None;
    }
    let winner = v
        .get("winner")
        .and_then(|w| w.as_str())
        .map(|s| s.to_string())
        .unwrap_or_else(|| {
            // Fall back to the highest rubric total if the judge omitted a winner.
            scores
                .iter()
                .max_by_key(|s| s.total())
                .map(|s| s.vendor.clone())
                .unwrap_or_default()
        });
    let reasoning = v
        .get("reasoning")
        .and_then(|r| r.as_str())
        .unwrap_or("(no reasoning given)")
        .trim()
        .to_string();
    Some(JudgeVerdict {
        scores,
        winner,
        reasoning,
